import sys, heapq

def main():
    data = sys.stdin.read().split()
    N, K = int(data[0]), int(data[1])
    occ = sorted(int(x) for x in data[2:2 + K])
    M = int(data[2 + K])
    heap = []

    def push(L, R):
        # L or R is 0 / N + 1 for "no occupied seat on that side"
        if L == 0:
            if R > 1:
                heapq.heappush(heap, (-(R - 1), 1, L, R))
        elif R == N + 1:
            if L < N:
                heapq.heappush(heap, (-(N - L), N, L, R))
        elif R - L >= 2:
            heapq.heappush(heap, (-((R - L) // 2), (L + R) // 2, L, R))

    push(0, occ[0])
    for i in range(K - 1):
        push(occ[i], occ[i + 1])
    push(occ[-1], N + 1)
    out = []
    for _ in range(M):
        d, s, L, R = heapq.heappop(heap)
        out.append(s)
        push(L, s)
        push(s, R)
    print('\n'.join(map(str, out)))

